# Additional visual walkthroughs, inserted into their respective chapters.
visual_additions = {}
def visual_begin():
 global visual_start
 visual_start = len(parts)
def visual_end(key):
 visual_additions[key] = ''.join(parts[visual_start:])
 del parts[visual_start:]
def flow(title, states, explanations):
 # Each state: list of nodes (id, local x, y, text, kind), edges.
 nodes=[]; edges=[]; labels=[]
 for i, (ns, es) in enumerate(states):
  offset=i*300
  for n in ns:nodes.append((str(i)+n[0],offset+n[1],n[2],n[3],n[4] if len(n)>4 else ''))
  for e in es:edges.append((str(i)+e[0],str(i)+e[1],*(e[2:])))
  labels.append((offset+15,27,f'Шаг {i+1}'))
  if i<2:labels.append((offset+277,130,'→'))
 fig(title,nodes,edges,labels,height=330)
 for i,ex in enumerate(explanations,1):p(f'<b>Шаг {i}.</b> '+ex)
